Code.NativeIaC:
```bicep
param storageAccountName string
param workspaceId string

resource sa 'Microsoft.Storage/storageAccounts@2023-01-01' existing = {
  name: storageAccountName
  resource queue 'queueServices' existing = {
    name: 'default'
  }
}

resource diag 'Microsoft.Insights/diagnosticSettings@2021-05-01-preview' = {
  name: 'example_resource'
  scope: sa::queue
  properties: {
    workspaceId: workspaceId
    logs: [
      { category: 'StorageRead', enabled: true }   // Required
      { category: 'StorageWrite', enabled: true }   // Required
      { category: 'StorageDelete', enabled: true }  // Required
    ]
  }
}
```

Code.Terraform:
```hcl
resource "azurerm_monitor_diagnostic_setting" "example_resource" {
  name                       = "example_resource"
  target_resource_id         = "${azurerm_storage_account.example_resource.id}/queueServices/default"
  log_analytics_workspace_id = "<example_resource_id>"

  enabled_log {
    category = "StorageRead"  # Required
  }
  enabled_log {
    category = "StorageWrite"  # Required
  }
  enabled_log {
    category = "StorageDelete"  # Required
  }
}
```
